// Turn Jev's answers into flat fields your CRM can store.
// Jev's guess goes in timezone_inferred, so it never overwrites a value a person entered.
const THRESHOLD = 0.8; // minimum confidence to write the time zone automatically

return $input.all().map((item) => {
  const { answers, model, me, lead } = item.json;
  const tz = answers.timezone;
  const confident = tz.choice !== 'unknown' && tz.confidence >= THRESHOLD;
  return {
    json: {
      ...lead,
      timezone_inferred: tz.choice,
      timezone_confidence: Number(tz.confidence.toFixed(2)),
      timezone_status: confident ? 'auto' : 'review',
      decision_maker_probability: Number(answers.is_decision_maker.noul.toFixed(2)),
      lead_fit_score: Number(answers.lead_fit.score.toFixed(2)), // 0 = not a fit, 3 = ideal
      jev_model: model,
      me, // kept for the next step; dropped before write-back
    },
  };
});

// Plain logic, no AI. Jev already picked the time zone; this is just arithmetic.
// Find the next 9am in the lead's time zone, then show it on my clock.
return $input.all().map((item) => {
  const { me, ...lead } = item.json;
  const now = DateTime.now();
  let theirs = now.setZone(lead.timezone_inferred).set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
  if (theirs <= now) theirs = theirs.plus({ days: 1 });
  const mine = theirs.setZone(me.timezone);
  return {
    json: {
      ...lead,
      send_at_their_time: theirs.toFormat('ccc h:mm a ZZZZ'),
      send_at_my_time: mine.toFormat('ccc h:mm a ZZZZ'),
      send_at_utc: theirs.toUTC().toISO(),
    },
  };
});
